from typing import Optional
import bs4
from bs4 import BeautifulSoup


class ScreenDumpParser:
    """
        Make dump smaller and easier, gives only "useful" (not empty) elements from dump.
        MAKE IT RECURSIVELY!!!
    """

    def __init__(self):
        self.tmpResult: list = []  # final result, collect all parsed elements

    def _checkIfUseful(self, element: bs4.element.Tag) -> bool:
        """
            Check if element is "not empty" (or useful for the system)
        """
        return bool(element.get('bounds'))

    def _getNonEmpty(self, element: bs4.element.Tag) -> Optional[bs4.element.Tag]:
        """
            Recursively get all non-empty elements
        """
        children = element.find_all("node", recursive=False)

        if all([
            self._checkIfUseful(element),
            element not in self.tmpResult,
            len(children) == 0,
        ]):
            self.tmpResult.append(element)

        for child in children:
            self._getNonEmpty(child)

    def parse(self, xml: str) -> list[bs4.element.Tag]:
        """
            to remove empty elements without info and/or trash
        """

        self.tmpResult.clear() # clear prev information
        soup = BeautifulSoup(xml, 'xml')
        root: bs4.element.Tag = soup.find('hierarchy') # main tree for the dump

        self._getNonEmpty(root)
        return self.tmpResult


